function demoDB() {
  const S = load('aou_social', { conns: {}, threads: {}, rooms: {}, meetings: [], feed: [], requests: [] });
  const put = () => save('aou_social', S);
  const listeners = [];
  return {
    live: false,
    async init() { return true; },
    getMe() { return load('aou_me', null); },
    async saveMe(me) { save('aou_me', me); return me; },
    async signUp(me) { me.id = me.id || uid(); save('aou_me', me); return me; },
    async signIn() { return load('aou_me', null); },
    async signOut() { /* demo keeps the local profile */ },
    async profile(id) { const { data } = await sb.from('profiles').select('*').eq('id', id).maybeSingle(); return data ? fromRow(data) : null; },
    fx(payload) { if (this._world) this._world.send({ type: 'broadcast', event: 'fx', payload }); },
    async profiles() { return []; },
    connStatus(id) { return S.conns[id] || null; },
    async wave(p) { S.conns[p.id] = S.conns[p.id] || { status: 'waved', at: now(), name: p.name }; put(); if (p.demo) setTimeout(() => { listeners.forEach(f => f({ type: 'wave', from: p })); }, 1600); },
    async connect(p) { S.conns[p.id] = { status: 'pending', at: now(), name: p.name }; put(); if (p.demo && p.mode !== 'dnd') setTimeout(() => { S.conns[p.id].status = 'connected'; put(); listeners.forEach(f => f({ type: 'accepted', from: p })); }, 2200); },
    async respond(id, ok) { if (S.conns[id]) { S.conns[id].status = ok ? 'connected' : 'declined'; put(); } },
    connections() { return Object.entries(S.conns).filter(([, c]) => c.status === 'connected').map(([id, c]) => ({ id, name: c.name })); },
    thread(id) { return S.threads[id] || []; },
    async send(p, body) { const t = S.threads[p.id] = S.threads[p.id] || []; t.push({ me: true, body, at: now() }); put(); if (p.demo) setTimeout(() => { t.push({ me: false, body: REPLIES[Math.floor(Math.random() * REPLIES.length)], at: now() }); put(); listeners.forEach(f => f({ type: 'message', from: p })); }, 1800); },
    room(id) { return S.rooms[id] || [{ name: 'Lumi', body: 'Welcome to ' + id.replace(/-/g, ' ') + '. Be kind, be you. 🌍', at: now() }]; },
    async sendRoom(id, me, body) { const r = S.rooms[id] = this.room(id); r.push({ name: me.name, body, at: now(), me: true }); if (r.length > 80) r.shift(); put(); },
    onEvent(f) { listeners.push(f); },
    async matchPosts() { return [...load('aou_match', []), ...DEMO_POSTS]; },
    async addMatch(p) { const a = load('aou_match', []); a.unshift(p); save('aou_match', a); return p; },
    async claims() { return load('aou_claims', []); },
    async claim(c) { const a = load('aou_claims', []).filter(x => x.owner !== c.owner && x.id !== c.id); a.push(c); save('aou_claims', a); return c; },
    async meeting(p, m) { S.meetings.push(Object.assign({ to: p.id, toName: p.name, status: 'sent', at: now() }, m)); put(); if (p.demo) setTimeout(() => listeners.forEach(f => f({ type: 'meeting', from: p })), 2000); },
    meetings() { return S.meetings; },
    async feed() { return [...S.feed, ...DEMO_FEED]; },
    async post(me, p) { S.feed.unshift(Object.assign({ id: uid(), author: me.id, name: me.name, at: now() }, p)); put(); },
    async wish(me, text) { const w = load('aou_wishes', []); w.push({ text, at: now() }); save('aou_wishes', w); },
    presence() { },
  };
}

function shrinkFace(src) { return new Promise((res) => { const im = new Image(); im.onload = () => { const c = document.createElement('canvas'); c.width = 128; c.height = 160; c.getContext('2d').drawImage(im, 0, 0, 128, 160); let u = ''; try { u = c.toDataURL('image/webp', 0.82); } catch (e) { } if (!u || !u.startsWith('data:image/webp')) u = c.toDataURL('image/png'); res(u); }; im.onerror = () => res(null); im.src = src; }); }
async function liveDB(app, W) {
  const { createClient } = await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');
  const sb = createClient(CONFIG.SUPABASE_URL, CONFIG.SUPABASE_ANON_KEY);
  let me = null; const listeners = []; let conns = {}; const threads = {}; const rooms = {};
  const fire = (e) => listeners.forEach(f => f(e));
  const loadMe = async () => { const { data: { user } } = await sb.auth.getUser(); if (!user) { me = null; return null; } const { data } = await sb.from('profiles').select('*').eq('id', user.id).maybeSingle(); me = data ? fromRow(data) : null; if (me) { const { data: lb } = await sb.from('lifeboards').select('data').eq('id', user.id).maybeSingle(); me.lifeboard = (lb && lb.data) || {}; } return me; };
  const fromRow = (r) => ({ id: r.id, username: r.username, name: r.display_name, mode: r.mode, paths: r.paths || [], city: r.city, bio: r.bio, causes: r.causes || [], looking: r.looking_for, attractor: r.attractor, avatar: r.avatar || {}, home: r.home || {}, ref: r.referred_by });
  const toRow = (m) => ({ id: m.id, username: m.username, display_name: m.name, mode: m.mode, paths: m.paths, city: m.city, bio: m.bio, causes: m.causes, looking_for: m.looking, attractor: m.attractor, avatar: m.avatar, home: m.home, referred_by: m.ref || null, updated_at: now() });
  const refreshConns = async () => { if (!me) return; const { data } = await sb.from('connections').select('*').or(`requester.eq.${me.id},addressee.eq.${me.id}`); conns = {}; for (const c of data || []) { const other = c.requester === me.id ? c.addressee : c.requester; conns[other] = { status: c.status === 'accepted' ? 'connected' : (c.requester === me.id ? (c.kind === 'wave' ? 'waved' : 'pending') : 'incoming'), row: c }; } };
  const DB = {
    live: true, sb,
    async init() { await loadMe(); await refreshConns(); if (me) this._subscribe(); sb.auth.onAuthStateChange(async () => { await loadMe(); await refreshConns(); }); return true; },
    getMe() { return me; },
    async saveMe(m) { me = Object.assign(me || {}, m); const { error } = await sb.from('profiles').upsert(toRow(me)); if (error) throw error; if (me.lifeboard) await sb.from('lifeboards').upsert({ id: me.id, data: me.lifeboard, updated_at: now() }); return me; },
    async signUp(m) { const { data, error } = await sb.auth.signUp({ email: m.email, password: m.password }); if (error) throw error; const id = data.user && data.user.id; if (!id) throw new Error('Check your email to confirm, then sign in.'); m.id = id; delete m.password; me = m; if (data.session) { await this.saveMe(m); this._subscribe(); } else save('aou_pending_profile', m); return me; },
    async signIn(email, password) { const { error } = await sb.auth.signInWithPassword({ email, password }); if (error) throw error; await loadMe(); if (!me) { const p = load('aou_pending_profile', null); const { data: { user } } = await sb.auth.getUser(); if (p && user) { p.id = user.id; await this.saveMe(p); } } await refreshConns(); this._subscribe(); return me; },
    async signOut() { await sb.auth.signOut(); me = null; },
    async profiles() { const { data } = await sb.from('profiles').select('id,username,display_name,mode,paths,city,bio,causes,looking_for,attractor,avatar').limit(300); return (data || []).map(fromRow); },
    connStatus(id) { return conns[id] ? conns[id].status : null; },
    async wave(p) { await sb.from('connections').insert({ requester: me.id, addressee: p.id, kind: 'wave', status: 'pending' }); await refreshConns(); },
    async connect(p) { const ex = conns[p.id]; if (ex && ex.row && ex.row.kind === 'wave' && ex.row.requester === me.id) await sb.from('connections').update({ kind: 'connect' }).eq('id', ex.row.id); else if (ex && ex.status === 'incoming') await sb.from('connections').update({ status: 'accepted' }).eq('id', ex.row.id); else await sb.from('connections').insert({ requester: me.id, addressee: p.id, kind: 'connect', status: 'pending' }); await refreshConns(); },
    async respond(id, ok) { const c = conns[id]; if (c && c.row) await sb.from('connections').update({ status: ok ? 'accepted' : 'declined' }).eq('id', c.row.id); await refreshConns(); },
    connections() { return Object.entries(conns).filter(([, c]) => c.status === 'connected').map(([id]) => ({ id, name: (W.profileCache.get(id) || {}).name || 'Friend' })); },
    incoming() { return Object.entries(conns).filter(([, c]) => c.status === 'incoming').map(([id, c]) => ({ id, kind: c.row.kind, name: (W.profileCache.get(id) || {}).name || 'Someone' })); },
    thread(id) { return threads[id] || []; },
    async loadThread(id) { const { data } = await sb.from('messages').select('*').or(`and(sender.eq.${me.id},recipient.eq.${id}),and(sender.eq.${id},recipient.eq.${me.id})`).order('created_at').limit(200); threads[id] = (data || []).map(m => ({ me: m.sender === me.id, body: m.body, at: m.created_at })); return threads[id]; },
    async send(p, body) { const { error } = await sb.from('messages').insert({ sender: me.id, recipient: p.id, body }); if (error) throw error; (threads[p.id] = threads[p.id] || []).push({ me: true, body, at: now() }); },
    room(id) { return rooms[id] || []; },
    async loadRoom(id) { const { data } = await sb.from('messages').select('*').eq('room', id).order('created_at', { ascending: false }).limit(60); rooms[id] = (data || []).reverse().map(m => ({ name: m.sender_name, body: m.body, at: m.created_at, me: me && m.sender === me.id })); return rooms[id]; },
    async sendRoom(id, m, body) { const { error } = await sb.from('messages').insert({ sender: m.id, sender_name: m.name, room: id, body }); if (error) throw error; },
    onEvent(f) { listeners.push(f); },
    async matchPosts() { const { data } = await sb.from('match_posts').select('*').eq('status', 'open').order('created_at', { ascending: false }).limit(200); return (data || []).map(r => ({ id: r.id, user: r.user_id, name: r.user_name, kind: r.kind, cat: r.category, title: r.title, details: r.details, city: r.city, at: r.created_at })); },
    async addMatch(p) { const { error } = await sb.from('match_posts').insert({ user_id: me.id, user_name: me.name, kind: p.kind, category: p.cat, title: p.title, details: p.details, city: p.city }); if (error) throw error; return p; },
    async claims() { const { data } = await sb.from('plots').select('*').limit(5000); return (data || []).map(r => ({ id: r.id, owner: r.owner, name: r.name, style: r.style, skin: r.skin, x: r.x, z: r.z })); },
    async claim(c) { await sb.from('plots').delete().eq('owner', me.id); const { error } = await sb.from('plots').insert({ id: c.id, owner: me.id, name: c.name, style: c.style, skin: c.skin, x: c.x, z: c.z }); if (error) throw error; return c; },
    async meeting(p, m) { const { error } = await sb.from('meeting_requests').insert({ from_user: me.id, to_user: p.id, kind: m.kind, when_at: m.when, note: m.note }); if (error) throw error; },
    meetings() { return []; },
    async feed() { const ids = [me.id, ...Object.keys(conns).filter(k => conns[k].status === 'connected')]; const { data } = await sb.from('posts').select('*').in('author', ids).order('created_at', { ascending: false }).limit(100); return (data || []).map(r => ({ id: r.id, author: r.author, name: r.author_name, kind: r.kind, body: r.body, at: r.created_at })); },
    async post(m, p) { await sb.from('posts').insert({ author: m.id, author_name: m.name, kind: p.kind, body: p.body }); },
    async wish(m, text) { await sb.from('wishes').insert({ user_id: m ? m.id : null, text }); },
    _subscribe() { if (this._subbed || !me) return; this._subbed = true;
      sb.channel('inbox-' + me.id).on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages', filter: 'recipient=eq.' + me.id }, (pl) => { const m = pl.new; (threads[m.sender] = threads[m.sender] || []).push({ me: false, body: m.body, at: m.created_at }); fire({ type: 'message', from: W.profileCache.get(m.sender) || { id: m.sender, name: 'Someone' } }); })
        .on('postgres_changes', { event: '*', schema: 'public', table: 'connections', filter: 'addressee=eq.' + me.id }, async (pl) => { await refreshConns(); const r = pl.new; fire({ type: r.kind === 'wave' ? 'wave' : 'request', from: W.profileCache.get(r.requester) || { id: r.requester, name: 'Someone' } }); })
        .on('postgres_changes', { event: 'UPDATE', schema: 'public', table: 'connections', filter: 'requester=eq.' + me.id }, async (pl) => { await refreshConns(); if (pl.new.status === 'accepted') fire({ type: 'accepted', from: W.profileCache.get(pl.new.addressee) || { id: pl.new.addressee, name: 'Someone' } }); })
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'messages', filter: 'room=neq.' }, (pl) => { const m = pl.new; if (!m.room) return; (rooms[m.room] = rooms[m.room] || []).push({ name: m.sender_name, body: m.body, at: m.created_at, me: m.sender === me.id }); fire({ type: 'room', room: m.room }); })
        .subscribe(); },
    /* v41 area split: everyone stays on 'world' for hugs, presentations and who-left notices,
       but positions only travel inside your 250 m area, so you only receive the people near you. */
    presence(getState) { const ch = sb.channel('world', { config: { presence: { key: me ? me.id : uid() }, broadcast: { self: false } } }); this._world = ch;
      const onPos = ({ payload }) => { if (!payload || (me && payload.id === me.id)) return; W.profileCache.set(payload.id, payload.profile); W.remoteUpsert(payload.id, payload); };
      ch.on('broadcast', { event: 'fx' }, ({ payload }) => { try { W.onFx && W.onFx(payload); } catch (e) { } });
      ch.on('presence', { event: 'leave' }, ({ key }) => W.remoteRemove(key));
      let area = null, areaKey = ''; const cell = (x, z) => Math.round(x / 250) + '_' + Math.round(z / 250);
      const joinArea = (k) => { if (area) { try { sb.removeChannel(area); } catch (e) { } } areaKey = k; area = sb.channel('pos-' + k, { config: { broadcast: { self: false } } }); area.on('broadcast', { event: 'pos' }, onPos); area.subscribe(); };
      ch.subscribe(async (st) => { if (st !== 'SUBSCRIBED') return; await ch.track({ online_at: now() }); let last = '', lastSent = 0;
        setInterval(() => { const s = getState(); if (!s) return; const k = cell(s.x, s.z); if (k !== areaKey) { joinArea(k); last = ''; } }, 1500);
        setInterval(() => { if (document.hidden || !area) return; const s = getState(); if (!s) return; const k = [Math.round(s.x * 3), Math.round(s.z * 3), Math.round(s.yaw * 8), s.mode, s.profile && s.profile.avatar && s.profile.avatar.v].join(','); const t = Date.now(); if (k === last && t - lastSent < 5000) return; last = k; lastSent = t; area.send({ type: 'broadcast', event: 'pos', payload: s }); }, 400); }); },
  };
  return DB;
}

