  const words = (s) => new Set(String(s).toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 3 && !['with', 'some', 'help', 'need', 'have', 'used', 'free', 'gently', 'size', 'from', 'that', 'this', 'for'].includes(w)).map(w => w.replace(/s$/, '')));
  const findMatch = (p, all) => { const a = words(p.title + ' ' + (p.details || '')); let best = null, bs = 0; for (const q of all) { if (q.kind === p.kind || q.user === p.user || q.cat !== p.cat) continue; const b = words(q.title + ' ' + (q.details || '')); let s = 0; for (const w of a) if (b.has(w)) s++; if (s > bs) { bs = s; best = q; } } return bs >= 1 ? best : null; };
  function weHaveAMatch(p, q) { app.celebrate('🤝'); const m = modal('🎉 WE HAVE A MATCH', `<div class="aou-match"><div class="aou-post ${p.kind}"><span class="k">${p.kind === 'have' ? 'YOU HAVE' : 'YOU NEED'}</span><b>${esc(p.title)}</b></div><div class="eq">↔</div><div class="aou-post ${q.kind}"><span class="k">${esc(q.name)} ${q.kind === 'have' ? 'HAS' : 'NEEDS'}</span><b>${esc(q.title)}</b><small>${esc(q.city || '')}</small></div></div><div class="aou-row"><button class="aou-btn primary" id="wm-go">💬 Reach out to ${esc(q.name)}</button></div>`); $('#wm-go', m).onclick = () => { const pp = findPerson(q.user) || { id: q.user, name: q.name }; openProfile(pp); }; }

