  function mailbox() { if (W.openHub) { W.openHub(); return; } const m = modal('📬 Zach\'s mailbox', `<p>Hi, I'm Zach. I'm building allofus.one so all of us can find each other, help each other, and build something good together. Say hi any time.</p><div class="aou-row"><a class="aou-btn primary" href="https://www.facebook.com/share/1FCtkAgToH/" target="_blank" rel="noopener">📘 Find me on Facebook</a><button class="aou-btn" id="mb-mail">📧 Email Zach</button><a class="aou-btn" href="https://zacharytyewennstedt.com/" target="_blank" rel="noopener">✨ zacharytyewennstedt.com</a></div><p class="muted2" id="mb-show"></p>`); $('#mb-mail', m).onclick = () => { const e = ZEMAIL(); $('#mb-show', m).textContent = e; location.href = 'mailto:' + e + '?subject=' + encodeURIComponent('Hi from allofus.one'); }; }
