        $$('[data-h]', main).forEach(c => c.onchange = () => { const h = lb.habits.find(x => x.id === c.dataset.h); h.days = c.checked ? [...new Set([...h.days, d])] : h.days.filter(x => x !== d); persist(); R.wellness(); }); $$('[data-hd]', main).forEach(b => b.onclick = () => { lb.habits = lb.habits.filter(h => h.id !== b.dataset.hd); persist(); R.wellness(); });
